package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"reflect"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
)

type backlogLiveGetter interface {
	GetNoCache(context.Context, string, map[string]string) (json.RawMessage, error)
}

type backlogLiveMutator interface {
	backlogLiveGetter
	Patch(context.Context, string, any) (json.RawMessage, int, error)
}

type backlogCandidate struct {
	ID            string `json:"id"`
	Identifier    string `json:"identifier,omitempty"`
	Name          string `json:"name,omitempty"`
	Priority      string `json:"priority,omitempty"`
	State         string `json:"state,omitempty"`
	AssigneeCount int    `json:"assignee_count"`
	LabelCount    int    `json:"label_count"`
	Point         any    `json:"point,omitempty"`
	TargetDate    any    `json:"target_date,omitempty"`
}

type backlogTriageResult struct {
	Project    string             `json:"project"`
	Candidates []backlogCandidate `json:"candidates"`
	Count      int                `json:"count"`
}

type backlogApplyItem struct {
	ID       string         `json:"id"`
	Before   map[string]any `json:"before"`
	Desired  map[string]any `json:"desired"`
	After    map[string]any `json:"after,omitempty"`
	Verified bool           `json:"verified"`
}

type backlogApplyResult struct {
	Project string             `json:"project"`
	DryRun  bool               `json:"dry_run"`
	Items   []backlogApplyItem `json:"items"`
}

func newWorkflowBacklogTriageCmd(flags *rootFlags) *cobra.Command {
	var slug, projectID string
	var limit int

	cmd := &cobra.Command{
		Use:   "backlog-triage",
		Short: "Inspect live, uncycled backlog candidates without changing them.",
		Long: `Read the project's current work items directly from Plane and summarize
only items with no cycle assignment. This command never mutates Plane.`,
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) != 0 {
				return usageErr(fmt.Errorf("backlog-triage takes no positional arguments; pass --project <uuid>"))
			}
			if projectID == "" {
				return usageErr(fmt.Errorf("--project is required"))
			}
			if limit < 1 {
				return usageErr(fmt.Errorf("--limit must be greater than zero"))
			}
			slug = effectiveSlug(flags, slug)
			if slug == "" || slug == "my-workspace" {
				return usageErr(fmt.Errorf("workspace not set: pass --workspace <slug>, --slug <slug>, export %s, or run 'plane-pp-cli workspaces use <slug>'", envWorkspaceSlug))
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			applyClientSlug(c, slug)
			result, err := triageBacklog(cmd.Context(), c, projectID, limit)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			raw, err := json.Marshal(result)
			if err != nil {
				return err
			}
			return printOutputWithFlags(cmd.OutOrStdout(), raw, flags)
		},
	}
	cmd.Flags().StringVar(&slug, "slug", "", "Workspace slug; overridden by the global --workspace (defaults to $"+envWorkspaceSlug+")")
	cmd.Flags().StringVar(&projectID, "project", "", "Project UUID (required)")
	cmd.Flags().IntVar(&limit, "limit", 50, "Maximum number of uncycled candidates to return")
	return cmd
}

func newWorkflowBacklogApplyCmd(flags *rootFlags) *cobra.Command {
	var slug, projectID, priority, state, targetDate string
	var assignees, labels []string
	var point int

	cmd := &cobra.Command{
		Use:   "backlog-apply <issue_uuid> [issue_uuid...]",
		Short: "Preview, apply, and live-verify the same backlog fields on explicit work items.",
		Long: `Update explicitly named work items only. Every target is fetched live before
any PATCH is attempted. Pass the global --dry-run flag for a live preview with
no mutation. After each PATCH, the item is fetched live again and normalized
field values are verified against the request.`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return usageErr(fmt.Errorf("at least one issue_uuid is required"))
			}
			if projectID == "" {
				return usageErr(fmt.Errorf("--project is required"))
			}
			slug = effectiveSlug(flags, slug)
			if slug == "" || slug == "my-workspace" {
				return usageErr(fmt.Errorf("workspace not set: pass --workspace <slug>, --slug <slug>, export %s, or run 'plane-pp-cli workspaces use <slug>'", envWorkspaceSlug))
			}
			body := map[string]any{}
			if cmd.Flags().Changed("priority") {
				body["priority"] = emptyStringAsNil(priority)
			}
			if cmd.Flags().Changed("state") {
				body["state"] = emptyStringAsNil(state)
			}
			if cmd.Flags().Changed("assignees") {
				body["assignees"] = cleanStringList(assignees)
			}
			if cmd.Flags().Changed("labels") {
				body["labels"] = cleanStringList(labels)
			}
			if cmd.Flags().Changed("point") {
				body["point"] = point
			}
			if cmd.Flags().Changed("target-date") {
				body["target_date"] = emptyStringAsNil(targetDate)
			}
			if len(body) == 0 {
				return usageErr(fmt.Errorf("at least one mutation flag is required"))
			}
			for _, id := range args {
				if !issueUUIDPattern.MatchString(id) {
					return usageErr(fmt.Errorf("issue_uuid %q is not a canonical UUID", id))
				}
			}
			c, err := flags.newClient()
			if err != nil {
				return err
			}
			applyClientSlug(c, slug)
			result, err := applyBacklog(cmd.Context(), c, projectID, args, body, flags.dryRun)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			raw, err := json.Marshal(result)
			if err != nil {
				return err
			}
			return printOutputWithFlags(cmd.OutOrStdout(), raw, flags)
		},
	}
	cmd.Flags().StringVar(&slug, "slug", "", "Workspace slug; overridden by the global --workspace (defaults to $"+envWorkspaceSlug+")")
	cmd.Flags().StringVar(&projectID, "project", "", "Project UUID (required)")
	cmd.Flags().StringVar(&priority, "priority", "", "Priority value; pass an empty value to clear")
	cmd.Flags().StringVar(&state, "state", "", "State UUID; pass an empty value to clear")
	cmd.Flags().StringSliceVar(&assignees, "assignees", nil, "Assignee UUIDs (comma-separated or repeatable); pass an empty value to clear")
	cmd.Flags().StringSliceVar(&labels, "labels", nil, "Label UUIDs (comma-separated or repeatable); pass an empty value to clear")
	cmd.Flags().IntVar(&point, "point", 0, "Estimate point, including zero")
	cmd.Flags().StringVar(&targetDate, "target-date", "", "Target date (YYYY-MM-DD); pass an empty value to clear")
	return cmd
}

func triageBacklog(ctx context.Context, get backlogLiveGetter, projectID string, limit int) (backlogTriageResult, error) {
	result := backlogTriageResult{Project: projectID, Candidates: []backlogCandidate{}}
	path := fmt.Sprintf("/projects/%s/issues/", projectID)
	raw, err := get.GetNoCache(ctx, path, map[string]string{
		"per_page": "100",
		"expand":   "state,assignees,labels",
	})
	if err != nil {
		return result, fmt.Errorf("reading live project backlog: %w", err)
	}
	items, err := decodeBacklogItems(raw)
	if err != nil {
		return result, err
	}
	for _, item := range items {
		if !isEmptyServerValue(item["cycle"]) || !isEmptyServerValue(item["cycle_id"]) {
			continue
		}
		candidate := backlogCandidate{
			ID:            normalizedID(item["id"]),
			Identifier:    workItemIdentifier(item),
			Name:          stringValue(item["name"]),
			Priority:      stringValue(item["priority"]),
			State:         normalizedID(firstPresent(item, "state", "state_id")),
			AssigneeCount: len(normalizedIDList(item["assignees"])),
			LabelCount:    len(normalizedIDList(item["labels"])),
			Point:         item["point"],
			TargetDate:    item["target_date"],
		}
		result.Candidates = append(result.Candidates, candidate)
		if len(result.Candidates) == limit {
			break
		}
	}
	result.Count = len(result.Candidates)
	return result, nil
}

func applyBacklog(ctx context.Context, api backlogLiveMutator, projectID string, ids []string, desired map[string]any, dryRun bool) (backlogApplyResult, error) {
	result := backlogApplyResult{
		Project: projectID,
		DryRun:  dryRun,
		Items:   make([]backlogApplyItem, 0, len(ids)),
	}

	// Complete every live preflight before the first mutation. A missing or
	// inaccessible target therefore fails closed without a partial batch.
	for _, id := range ids {
		path := fmt.Sprintf("/projects/%s/issues/%s/", projectID, id)
		raw, err := api.GetNoCache(ctx, path, nil)
		if err != nil {
			return result, fmt.Errorf("live preview for work item %s: %w", id, err)
		}
		before, err := decodeBacklogObject(raw)
		if err != nil {
			return result, fmt.Errorf("decoding live preview for work item %s: %w", id, err)
		}
		result.Items = append(result.Items, backlogApplyItem{
			ID:      id,
			Before:  before,
			Desired: cloneMap(desired),
		})
	}
	if dryRun {
		return result, nil
	}

	for i := range result.Items {
		item := &result.Items[i]
		path := fmt.Sprintf("/projects/%s/issues/%s/", projectID, item.ID)
		if _, _, err := api.Patch(ctx, path, desired); err != nil {
			return result, fmt.Errorf("updating work item %s: %w", item.ID, err)
		}
		raw, err := api.GetNoCache(ctx, path, nil)
		if err != nil {
			return result, fmt.Errorf("live readback for work item %s: %w", item.ID, err)
		}
		after, err := decodeBacklogObject(raw)
		if err != nil {
			return result, fmt.Errorf("decoding live readback for work item %s: %w", item.ID, err)
		}
		item.After = after
		if err := verifyBacklogMutation(desired, after); err != nil {
			return result, fmt.Errorf("verifying work item %s: %w", item.ID, err)
		}
		item.Verified = true
	}
	return result, nil
}

func decodeBacklogItems(raw json.RawMessage) ([]map[string]any, error) {
	var direct []map[string]any
	if err := json.Unmarshal(raw, &direct); err == nil {
		return direct, nil
	}
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(raw, &envelope); err != nil {
		return nil, fmt.Errorf("decoding backlog response: %w", err)
	}
	for _, key := range []string{"results", "data", "items"} {
		if value, ok := envelope[key]; ok {
			if err := json.Unmarshal(value, &direct); err != nil {
				return nil, fmt.Errorf("decoding backlog response field %q: %w", key, err)
			}
			return direct, nil
		}
	}
	return nil, fmt.Errorf("decoding backlog response: expected an array or results/data/items array")
}

func decodeBacklogObject(raw json.RawMessage) (map[string]any, error) {
	var object map[string]any
	if err := json.Unmarshal(raw, &object); err != nil {
		return nil, err
	}
	if wrapped, ok := object["data"].(map[string]any); ok {
		return wrapped, nil
	}
	return object, nil
}

func verifyBacklogMutation(desired, actual map[string]any) error {
	var mismatches []string
	for field, want := range desired {
		got := actual[field]
		if !equivalentBacklogField(field, want, got) {
			mismatches = append(mismatches, fmt.Sprintf("%s: wanted %s, got %s", field, compactJSON(want), compactJSON(got)))
		}
	}
	sort.Strings(mismatches)
	if len(mismatches) > 0 {
		return fmt.Errorf("live readback mismatch: %s", strings.Join(mismatches, "; "))
	}
	return nil
}

func equivalentBacklogField(field string, want, got any) bool {
	switch field {
	case "state":
		return normalizedID(want) == normalizedID(got) ||
			(isEmptyServerValue(want) && isEmptyServerValue(got))
	case "assignees", "labels":
		return reflect.DeepEqual(normalizedIDList(want), normalizedIDList(got))
	case "point":
		return normalizedNumber(want) == normalizedNumber(got) ||
			(isEmptyServerValue(want) && isEmptyServerValue(got))
	default:
		if isEmptyServerValue(want) && isEmptyServerValue(got) {
			return true
		}
		return fmt.Sprint(want) == fmt.Sprint(got)
	}
}

func normalizedID(value any) string {
	switch v := value.(type) {
	case string:
		return v
	case map[string]any:
		return normalizedID(v["id"])
	default:
		return ""
	}
}

func normalizedIDList(value any) []string {
	if isEmptyServerValue(value) {
		return []string{}
	}
	var values []any
	switch v := value.(type) {
	case []any:
		values = v
	case []string:
		values = make([]any, len(v))
		for i := range v {
			values[i] = v[i]
		}
	default:
		values = []any{v}
	}
	ids := make([]string, 0, len(values))
	for _, value := range values {
		if id := normalizedID(value); id != "" {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	return ids
}

func normalizedNumber(value any) string {
	switch v := value.(type) {
	case json.Number:
		if f, err := v.Float64(); err == nil {
			return strconv.FormatFloat(f, 'f', -1, 64)
		}
		return v.String()
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case float32:
		return strconv.FormatFloat(float64(v), 'f', -1, 32)
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case string:
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			return strconv.FormatFloat(f, 'f', -1, 64)
		}
	}
	return ""
}

func isEmptyServerValue(value any) bool {
	if value == nil {
		return true
	}
	switch v := value.(type) {
	case string:
		return strings.TrimSpace(v) == ""
	case []any:
		return len(v) == 0
	case []string:
		return len(v) == 0 || (len(v) == 1 && strings.TrimSpace(v[0]) == "")
	case map[string]any:
		return len(v) == 0 || normalizedID(v) == ""
	}
	return false
}

func cleanStringList(values []string) []string {
	var cleaned []string
	for _, value := range values {
		for _, part := range strings.Split(value, ",") {
			if part = strings.TrimSpace(part); part != "" {
				cleaned = append(cleaned, part)
			}
		}
	}
	return cleaned
}

func emptyStringAsNil(value string) any {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	return value
}

func firstPresent(item map[string]any, keys ...string) any {
	for _, key := range keys {
		if value, ok := item[key]; ok {
			return value
		}
	}
	return nil
}

func workItemIdentifier(item map[string]any) string {
	if identifier := stringValue(item["identifier"]); identifier != "" {
		return identifier
	}
	project := stringValue(firstPresent(item, "project_identifier", "project"))
	sequence := normalizedNumber(item["sequence_id"])
	if project != "" && sequence != "" {
		return project + "-" + sequence
	}
	return sequence
}

func stringValue(value any) string {
	if value == nil {
		return ""
	}
	if id := normalizedID(value); id != "" {
		return id
	}
	return fmt.Sprint(value)
}

func compactJSON(value any) string {
	raw, err := json.Marshal(value)
	if err != nil {
		return fmt.Sprint(value)
	}
	return string(raw)
}

func cloneMap(input map[string]any) map[string]any {
	output := make(map[string]any, len(input))
	for key, value := range input {
		output[key] = value
	}
	return output
}
